// Writes lib/oaProductContent.ts from docs/products/*.md so the product text ships with the server bundle.
// Run: node scripts/build-oa-products.mjs   (the contract test checks that the generated file is up to date).
import { readFileSync, writeFileSync } from "node:fs";

const FILES = {
  "start-kit": "docs/products/01-start-kit.md",
  "ten-conversations": "docs/products/02-ten-conversations.md",
  "first-sale-texts": "docs/products/03-first-sale-texts.md"
};

export function render() {
  const entries = Object.entries(FILES).map(([key, path]) => `  ${JSON.stringify(key)}: ${JSON.stringify(readFileSync(new URL(`../${path}`, import.meta.url), "utf8"))}`);
  return `// Generated by scripts/build-oa-products.mjs from docs/products. Do not edit by hand.\nexport const OA_PRODUCT_CONTENT: Record<string, string> = {\n${entries.join(",\n")}\n};\n`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync(new URL("../lib/oaProductContent.ts", import.meta.url), render());
  console.log("lib/oaProductContent.ts written");
}
